fun grade(score: Int): String = when (score) {
    in 90..100 -> "A"
    in 80..89 -> "B"
    in 65..79 -> "C"
    in 0..64 -> "F"
    else -> "Invalid score"
}

fun main() {
    for (n in 1..15) {
        val text = when {
            n % 15 == 0 -> "FizzBuzz"
            n % 3 == 0 -> "Fizz"
            n % 5 == 0 -> "Buzz"
            else -> n.toString()
        }
        print("$text ")
    }
    println()
    for (i in 10 downTo 0 step 5) println(i)   // 10, 5, 0
    println(grade(84))                          // B
}

fun applyTwice(value: Int, operation: (Int) -> Int): Int = operation(operation(value))

fun measure(label: String, block: () -> Unit) {
    val start = System.nanoTime()
    block()
    println("$label took ${(System.nanoTime() - start) / 1_000} µs")
}

fun main() {
    val add: (Int, Int) -> Int = { a, b -> a + b }
    println(add(2, 3))                         // 5
    println(applyTwice(3) { it * 10 })          // 300

    val operations = mapOf<String, (Int, Int) -> Int>("+" to add, "*" to { a, b -> a * b })
    println(operations["*"]?.invoke(4, 5))      // 20

    measure("Sorting") { (1..10_000).shuffled().sorted() }
}

class Cart {
    private val _items = mutableListOf<String>()
    val items: List<String> get() = _items          // read-only view

    fun add(item: String) { _items += item }
}

fun main() {
    val colors = setOf("red", "green", "red")        // [red, green]: no duplicates
    val stock = mapOf("pen" to 12, "mug" to 0)
    println("${colors.size} colors, ${stock["pen"]} pens, mug in stock: ${stock.getValue("mug") > 0}")

    val cart = Cart()
    cart.add("Notebook")
    println(cart.items)                               // [Notebook]
    // cart.items.add("x")  does not compile: List has no add
}

data class Order(val customer: String, val amount: Double, val paid: Boolean)

fun main() {
    val orders = listOf(
        Order("Sara", 250.0, true), Order("Omar", 90.0, false),
        Order("Sara", 120.0, true), Order("Mona", 400.0, true),
    )

    val paidTotalByCustomer = orders
        .filter { it.paid }
        .groupBy { it.customer }
        .mapValues { (_, list) -> list.sumOf { it.amount } }
    println(paidTotalByCustomer)                         // {Sara=370.0, Mona=400.0}

    val topCustomer = paidTotalByCustomer.maxByOrNull { it.value }?.key
    println(topCustomer)                                 // Mona

    val firstBig = (1..1_000_000).asSequence().map { it * 3 }.first { it > 1_000 }
    println(firstBig)                                    // 1002
}

