fun readUserId(extras: Map<String, String?>): Int? {
    val raw = extras["userId"] ?: return null        // missing key
    return raw.toIntOrNull()                          // not a number
}

fun loadScreen(extras: Map<String, String?>): String {
    val id = readUserId(extras) ?: return "Open the profile from the list"
    return "Loading user $id"
}

