    println(config.isNotEmpty())
}

class BankAccount(val owner: String, initialBalance: Double = 0.0) {
    var balance: Double = initialBalance
        private set                                   // readable outside, changed only inside

    init {
        require(owner.isNotBlank()) { "Owner is required" }
        require(initialBalance >= 0) { "Balance can't be negative" }
    }

    val isEmpty: Boolean get() = balance == 0.0

    fun deposit(amount: Double) {
        require(amount > 0) { "Deposit must be positive" }
        balance += amount
    }

    fun withdraw(amount: Double): Boolean {
        if (amount <= 0 || amount > balance) return false
        balance -= amount
        return true
    }
}

fun main() {
    val account = BankAccount("Hana", 100.0)
    account.deposit(50.0)
    println("${account.withdraw(500.0)} ${account.balance} ${account.isEmpty}")   // false 150.0 false
}

interface Notifier {
    fun send(to: String, message: String)
}

class SmsNotifier : Notifier {
    override fun send(to: String, message: String) = println("SMS to $to: $message")
}

class FakeNotifier : Notifier {
    val sent = mutableListOf<String>()
    override fun send(to: String, message: String) { sent += message }
}

class OrderService(private val notifier: Notifier) {
    fun confirm(phone: String, orderId: Int) = notifier.send(phone, "Order $orderId confirmed")
}

fun main() {
    OrderService(SmsNotifier()).confirm("0100", 7)        // real use

    val fake = FakeNotifier()
    OrderService(fake).confirm("0100", 8)                 // in a test
    println(fake.sent)                                    // [Order 8 confirmed]
}

data class ScreenState(
    val isLoading: Boolean = true,
    val items: List<String> = emptyList(),
    val error: String? = null,
)

fun main() {
    var state = ScreenState()
    state = state.copy(isLoading = false, items = listOf("Tea", "Coffee"))
    println(state)        // ScreenState(isLoading=false, items=[Tea, Coffee], error=null)

    val (loading, items) = state
    println("$loading ${items.size}")                                   // false 2
    println(ScreenState() == ScreenState())                             // true: same content
}

enum class OrderStatus(val label: String) {
    PLACED("Placed"), SHIPPED("On the way"), DELIVERED("Delivered");
    val isFinal get() = this == DELIVERED
}

sealed interface PaymentResult {
    data class Paid(val receiptId: String) : PaymentResult
    data class Declined(val reason: String) : PaymentResult
    data object Cancelled : PaymentResult
}

fun message(result: PaymentResult): String = when (result) {
    is PaymentResult.Paid -> "Paid. Receipt ${result.receiptId}"
    is PaymentResult.Declined -> "Card declined: ${result.reason}"
    PaymentResult.Cancelled -> "Payment cancelled"
}

fun main() {
    println(OrderStatus.SHIPPED.label + " " + OrderStatus.SHIPPED.isFinal)   // On the way false
    println(message(PaymentResult.Declined("insufficient funds")))
    println(OrderStatus.entries.map { it.name })                             // [PLACED, SHIPPED, DELIVERED]
}

data class Page<T>(val items: List<T>, val page: Int, val hasMore: Boolean)

fun <T> Page<T>.next(load: (Int) -> Page<T>): Page<T>? = if (hasMore) load(page + 1) else null

fun <T : Comparable<T>> List<T>.isSortedAscending(): Boolean = zipWithNext().all { (a, b) -> a <= b }

fun String.maskEmail(): String {
    val name = substringBefore('@')
    return name.take(2) + "***@" + substringAfter('@')
}

fun main() {
    val first = Page(listOf("a", "b"), page = 1, hasMore = true)
    val second = first.next { p -> Page(listOf("c"), p, hasMore = false) }
    println(second)                                   // Page(items=[c], page=2, hasMore=false)
    println(listOf(1, 3, 7).isSortedAscending())      // true
    println("sara.ali@example.com".maskEmail())       // sa***@example.com
}

data class Notification(var title: String = "", var body: String = "", var silent: Boolean = false)

fun main() {
    val note = Notification().apply {           // this = Notification, returns the object
        title = "Order shipped"
        body = "Your order #1042 is on the way"
    }.also { println("Created: ${it.title}") }  // it = Notification, returns the object

    val couponCode: String? = "SAVE10"
    val discount = couponCode?.let { code ->    // runs only when not null, returns the last value
        if (code.startsWith("SAVE")) code.drop(4).toInt() else 0
    } ?: 0

    val summary = with(note) { "$title: ${body.length} characters" }   // compute from an object
    println("$discount% | $summary")
}

class Player {
    var started = false
        private set
    fun start() { started = true }
    fun pause() {
        check(started) { "Call start() before pause()" }
    }
}

fun readQuantity(text: String): Result<Int> = runCatching {
    val n = text.trim().toInt()
    require(n in 1..99) { "Quantity must be 1-99" }
    n
}

fun main() {
    println(readQuantity("3").getOrElse { -1 })                       // 3
    readQuantity("500").onFailure { println(it.message) }              // Quantity must be 1-99
    println(readQuantity("abc").exceptionOrNull()?.javaClass?.simpleName) // NumberFormatException

    val safe = runCatching { Player().pause() }
    println(safe.isFailure)                                            // true
}

// Two-sum: indexes of two numbers that add up to target, in one pass (O(n)).
fun twoSum(numbers: List<Int>, target: Int): Pair<Int, Int>? {
    val seen = HashMap<Int, Int>()                  // value -> index
    numbers.forEachIndexed { i, n ->
        seen[target - n]?.let { return it to i }
        seen[n] = i
    }
    return null
}

// Group words that use the same letters.
fun groupAnagrams(words: List<String>): List<List<String>> =
    words.groupBy { it.lowercase().toCharArray().sorted().joinToString("") }.values.toList()

fun isPalindrome(text: String): Boolean {
    val letters = text.lowercase().filter { it.isLetterOrDigit() }
    return letters == letters.reversed()
}

fun main() {
    println(twoSum(listOf(2, 7, 11, 15), 9))                       // (0, 1)
    println(groupAnagrams(listOf("listen", "silent", "enlist", "cat", "act")))
    println(isPalindrome("Never odd or even"))                     // true
}
